import {createCoach} from './coach.mjs?v=frame-6';
import {createGraphic} from './graphic.mjs?v=frame-6';
import {measure,summary,timing,visible} from './metrics.mjs';
const $=id=>document.getElementById(id);const video=$('video'),canvas=$('skeleton'),ctx=canvas.getContext('2d');
let sport='basketball',samples=[],marks={},file=null,url=null,model=null,busy=false,cancelled=false,loadID=0;
let graphic,coach;
const definitions={basketball:[['dip','最低點'],['rise','開始上升'],['release','球離手'],['finish','落地穩定']],golf:[['address','開始上桿'],['top','上桿頂點'],['impact','擊球'],['finish','收桿穩定']]};
const links=[[11,12],[11,13],[13,15],[12,14],[14,16],[11,23],[12,24],[23,24],[23,25],[25,27],[24,26],[26,28],[27,29],[29,31],[28,30],[30,32]];
const number=(v,d=1)=>Number.isFinite(v)?v.toFixed(d):'—';
function status(s){$('status').textContent=s;}
function busyState(value){busy=value;for(const e of document.querySelectorAll('.sport,#hand,#view,#file,#play,#back,#next,#seek,#export,#clearMarks,#marks button'))e.disabled=value||(['play','back','next','seek'].includes(e.id)&&!file)||(e.id==='export'&&!samples.length);$('analyze').disabled=value||!file;$('cancel').hidden=!value;$('progress').hidden=!value;graphic?.sync();coach?.sync();}
function renderMarks(){ $('marks').replaceChildren(...definitions[sport].map(([key,label])=>{const b=document.createElement('button');b.disabled=!file||busy;b.className=Number.isFinite(marks[key])?'set':'';const t=document.createElement('span');t.textContent=Number.isFinite(marks[key])?`${marks[key].toFixed(2)} s · 重新標記`:'＋ 標記目前畫面';b.append(document.createTextNode(label),t);b.onclick=()=>{marks[key]=video.currentTime;renderMarks();renderTiming();};return b;}));}
function renderTiming(){const t=timing(sport,marks);$('timing').textContent=!t.complete?'依序標記同一次動作。球離手／擊球時刻需由你看影片確認。':t.error??(sport==='golf'?`上桿 ${t.durations[0].toFixed(2)} s · 下桿 ${t.durations[1].toFixed(2)} s · 節奏比 ${t.ratio.toFixed(2)} : 1。描述這次動作，沒有套用理想比值。`:`最低點→上升 ${t.durations[0].toFixed(2)} s · 上升→離手 ${t.durations[1].toFixed(2)} s · 離手→穩定 ${t.durations[2].toFixed(2)} s。`);}
function configure(){graphic?.reset();coach?.reset();marks={};const golf=sport==='golf';$('cueTitle').textContent=golf?'讓節奏有跡可循。':'人球一起上。';$('cueText').textContent=golf?'OBSERVE · REPEAT · REFINE':'RISE WITH THE BALL';$('cueNote').textContent=golf?'先觀察上桿與下桿時序，再比較同角度的下一次動作。':'來自你的訓練筆記，作為觀察方向；不是這段影片的分析結論。';$('viewHint').textContent=golf?'正面適合觀察側移；後方適合觀察軀幹姿態。固定鏡頭，讓全身入鏡。':'側面最適合觀察軀幹前傾與畫面水平前移。固定鏡頭，完整拍到頭與腳。';samples=samples.map(s=>({...s,...measure(s.landmarks,video.videoWidth,video.videoHeight,$('hand').value,sport)}));renderMarks();renderTiming();renderReport();draw();}
for(const b of document.querySelectorAll('.sport'))b.onclick=()=>{if(busy)return;sport=b.dataset.sport;for(const x of document.querySelectorAll('.sport')){x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));}configure();};
$('hand').onchange=configure;$('view').onchange=()=>{renderReport();coach?.invalidate();};
async function loadFile(f){if(busy||!f)return;if(f.size>200*1024*1024){status('影片超過 200 MB，請先裁切成較短片段。');return;}if(!f.type.startsWith('video/')&&!/\.(mp4|mov|webm|m4v)$/i.test(f.name)){status('請選擇影片檔案。');return;}const id=++loadID;video.pause();if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(f);file=null;samples=[];marks={};graphic?.reset();coach?.reset();$('filename').textContent=f.name;$('empty').hidden=true;$('stageBadge').textContent='讀取影片';renderReport();renderTiming();ctx.clearRect(0,0,canvas.width,canvas.height);busyState(false);renderMarks();status('正在讀取影片…');video.onloadedmetadata=()=>{if(id!==loadID)return;if(!Number.isFinite(video.duration)||video.duration<=0){fail('無法讀取影片長度，請轉成 MP4（H.264）後重試。');return;}if(video.duration>120){fail('請先裁切至 120 秒內。建議每次分析一次完整動作。');return;}file=f;canvas.width=video.videoWidth;canvas.height=video.videoHeight;$('seek').max=video.duration;$('seek').value=0;busyState(false);renderMarks();$('stageBadge').textContent='原始影片';status('影片已就緒。按「分析這段動作」開始。');draw();};video.onerror=()=>{if(id===loadID)fail('瀏覽器無法解碼這支影片。MOV／HEVC 請轉成 MP4（H.264）後重試。');};video.src=url;video.load();}
function fail(message){file=null;samples=[];marks={};graphic?.reset();coach?.reset();busyState(false);renderMarks();renderReport();$('empty').hidden=false;$('stageBadge').textContent='影片無法使用';status(message);}
$('file').onchange=e=>loadFile(e.target.files[0]);const drop=$('drop');drop.ondragover=e=>{e.preventDefault();if(!busy)drop.classList.add('drag');};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');loadFile(e.dataTransfer.files[0]);};
$('play').onclick=async()=>{if(video.paused){try{await video.play();}catch{status('影片無法播放，請確認格式或重新選擇。');}}else video.pause();};video.onplay=()=>{$('play').textContent='Ⅱ';};video.onpause=()=>{$('play').textContent='▶';};$('speed').onchange=()=>{video.playbackRate=Number($('speed').value);};
$('seek').oninput=e=>{video.currentTime=Number(e.target.value);};$('back').onclick=()=>{video.pause();video.currentTime=Math.max(0,video.currentTime-1/30);};$('next').onclick=()=>{video.pause();video.currentTime=Math.min(video.duration,video.currentTime+1/30);};$('overlay').onchange=draw;$('clearMarks').onclick=()=>{marks={};renderMarks();renderTiming();};$('cancel').onclick=()=>{cancelled=true;status('正在取消，會清除未完成的分析。');};
function seek(t){return new Promise((resolve,reject)=>{if(Math.abs(video.currentTime-t)<.0001&&video.readyState>=2){resolve();return;}const timer=setTimeout(()=>{cleanup();reject(new Error('影片讀取逾時，請改用較短的 MP4 影片。'));},12000);const cleanup=()=>{clearTimeout(timer);video.removeEventListener('seeked',done);video.removeEventListener('error',error);};const done=()=>{cleanup();resolve();};const error=()=>{cleanup();reject(new Error('讀取影片時發生錯誤。'));};video.addEventListener('seeked',done);video.addEventListener('error',error);video.currentTime=t;});}
async function getModel(){if(model)return model;status('首次使用：正在下載姿勢模型…');const {FilesetResolver,PoseLandmarker}=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs');const vision=await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm');model=await PoseLandmarker.createFromOptions(vision,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_full/float16/1/pose_landmarker_full.task',delegate:'CPU'},runningMode:'IMAGE',numPoses:1,minPoseDetectionConfidence:.6,minPosePresenceConfidence:.6});return model;}
$('analyze').onclick=async()=>{if(!file||busy)return;video.pause();cancelled=false;busyState(true);samples=[];graphic?.reset();coach?.reset();renderReport();$('progress').value=0;const buffer=document.createElement('canvas'),scale=Math.min(1,960/video.videoWidth);buffer.width=Math.round(video.videoWidth*scale);buffer.height=Math.round(video.videoHeight*scale);const bc=buffer.getContext('2d');try{const detector=await getModel();if(cancelled)throw new Error('已取消分析。');const total=Math.max(1,Math.ceil(video.duration*15));for(let i=0;i<total;i++){if(cancelled)throw new Error('已取消分析。');const time=Math.min(i/15,Math.max(0,video.duration-.01));await seek(time);if(cancelled)throw new Error('已取消分析。');bc.drawImage(video,0,0,buffer.width,buffer.height);const result=detector.detect(buffer),landmarks=result.landmarks[0]??null;samples.push({time,landmarks,...measure(landmarks,video.videoWidth,video.videoHeight,$('hand').value,sport)});$('progress').value=(i+1)/total*100;status(`分析中 ${Math.round((i+1)/total*100)}% · ${i+1}/${total} 張畫面`);draw();await new Promise(r=>setTimeout(r,0));}status(`分析完成 · ${samples.length} 張取樣畫面。拖動時間軸檢視數據。`);$('stageBadge').textContent='分析完成 · 15 fps';await seek(0);graphic?.complete();}catch(error){samples=[];graphic?.reset();coach?.reset();$('stageBadge').textContent='原始影片';status(cancelled?'已取消分析，影片仍可回放。':`分析未完成：${error.message} 可檢查網路後重試；影片仍留在你的裝置。`);}finally{busyState(false);renderMarks();renderReport();draw();}};
function nearest(){if(!samples.length)return null;const i=Math.min(samples.length-1,Math.max(0,Math.round(video.currentTime*15)));const s=samples[i];return Math.abs(s.time-video.currentTime)<=.11?s:null;}
function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);const s=nearest();if(s?.landmarks&&$('overlay').checked){ctx.strokeStyle='#e8e8e8';ctx.fillStyle='#f1ffe2';ctx.lineWidth=Math.max(2,canvas.width/350);for(const [a,b] of links){const x=s.landmarks[a],y=s.landmarks[b];if(!visible(x)||!visible(y))continue;ctx.beginPath();ctx.moveTo(x.x*canvas.width,x.y*canvas.height);ctx.lineTo(y.x*canvas.width,y.y*canvas.height);ctx.stroke();}for(const p of s.landmarks.slice(11)){if(!visible(p))continue;ctx.beginPath();ctx.arc(p.x*canvas.width,p.y*canvas.height,Math.max(3,canvas.width/220),0,Math.PI*2);ctx.fill();}}const titles=[sport==='golf'?'前導臂手肘角度':'投籃側手肘角度',sport==='golf'?'前導側膝蓋角度':'投籃側膝蓋角度','軀幹偏離垂直'];$('metrics').querySelectorAll('article').forEach((a,i)=>{a.querySelector('span').textContent=titles[i];a.querySelector('strong').replaceChildren(document.createTextNode(number(s?.[['elbow','knee','lean'][i]])));const unit=document.createElement('small');unit.textContent='°';a.querySelector('strong').append(unit);a.querySelector('p').textContent=s?`取樣 ${s.time.toFixed(2)} s · 2D 投影`:'目前畫面 · 尚無有效量測';});$('seek').value=video.currentTime||0;$('clock').textContent=`${number(video.currentTime,2)} / ${number(video.duration||0,2)}`;drawChart();}
video.ontimeupdate=draw;video.onseeked=draw;function animate(){if(!video.paused&&!busy)draw();requestAnimationFrame(animate);}requestAnimationFrame(animate);
function drawChart(){const c=$('chart'),dpr=window.devicePixelRatio||1,w=c.clientWidth;if(!w)return;c.width=w*dpr;c.height=130*dpr;const x=c.getContext('2d');x.scale(dpr,dpr);x.font='9px sans-serif';x.fillStyle='#929292';for(const deg of [0,90,180]){const y=110-deg/180*95;x.strokeStyle='#e4e9dd';x.beginPath();x.moveTo(28,y);x.lineTo(w-8,y);x.stroke();x.fillText(String(deg),3,y+3);}if(!samples.length)return;for(const [key,color] of [['elbow','#6d6d6d'],['knee','#cc9156']]){x.strokeStyle=color;x.lineWidth=1.8;x.beginPath();let started=false;for(const s of samples){if(!Number.isFinite(s[key])){started=false;continue;}const px=28+s.time/video.duration*(w-38),py=110-s[key]/180*95;if(started)x.lineTo(px,py);else x.moveTo(px,py);started=true;}x.stroke();}x.strokeStyle='#959595';const px=28+video.currentTime/video.duration*(w-38);x.beginPath();x.moveTo(px,10);x.lineTo(px,112);x.stroke();x.fillText('0s',28,124);x.fillText(`${number(video.duration)}s`,w-38,124);}
$('chart').onclick=e=>{if(!file||busy)return;const r=$('chart').getBoundingClientRect();video.pause();video.currentTime=Math.max(0,Math.min(video.duration,(e.clientX-r.left-28)/(r.width-38)*video.duration));};window.addEventListener('resize',drawChart);
function reportLines(){const s=summary(samples);if(!samples.length)return ['先選擇影片。工具只根據實際偵測到的關節計算，不預填分數。'];const lines=[];const usable=s.lean?.count??0;if(s.detected/s.total<.7||usable/s.total<.7)lines.push('可用關節不足 70%：遮擋、距離或拍攝角度可能影響結果。先改善取景，再比較動作。');lines.push(sport==='basketball'?'觀察方向：先回看軀幹傾斜的變化，再看髖部在畫面的水平移動。兩者是不同量測，不能互相替代。':'觀察方向：查看前導臂手肘與膝蓋的角度曲線，並標記上桿頂點和擊球時刻，計算這次揮桿的節奏。');if($('view').value!=='side'&&sport==='basketball')lines.push('目前不是側面影片：軀幹角度不能解讀成前傾，水平移動也不能解讀成朝籃框前移。');if(s.lean)lines.push(`軀幹畫面投影角度範圍 ${number(s.lean.min)}°–${number(s.lean.max)}°（${s.lean.count}/${s.total} 張有效）。這是觀測範圍，並不代表好壞。`);if(s.horizontalSpan!==null)lines.push(`髖部水平活動範圍約 ${number(s.horizontalSpan*100)}% 軀幹長度。涵蓋整段影片的最大與最小值，並非單次起跳到落地的前移距離。`);lines.push(sport==='basketball'?'下一步：標記同一次投籃的最低點、上升、球離手與落地。回看「人球一起上」；本工具没有追蹤球，無法自動驗證人球同步或 wrist load。':'下一步：以同一拍攝角度比較不同揮桿。此工具沒有追蹤球桿，無法據此判定桿面、桿路、擊球點或球速。');return lines;}
function renderReport(){const s=summary(samples);$('analysisSummary').textContent=samples.length?`人體偵測 ${s.detected}/${s.total} 張（${Math.round(s.detected/s.total*100)}%）。有效角度：手肘 ${s.elbow?.count??0} 張、膝蓋 ${s.knee?.count??0} 張。低可信度關節不顯示數值。`:'分析完成後，這裡會顯示實際偵測覆蓋率、角度變化與畫面位移。';$('feedback').replaceChildren(...reportLines().map(text=>{const p=document.createElement('p');p.textContent=text;return p;}));$('export').disabled=!samples.length||busy;drawChart();}
function report(){return {version:1,sport,hand:$('hand').value,view:$('view').value,filename:file?.name??null,duration:video.duration||null,sampleRate:15,summary:summary(samples),marks,timing:timing(sport,marks),observations:reportLines(),limitations:'2D pose estimates only. No ball/club tracking, force, speed, 3D rotation or technique scores. Times refer to video playback.',samples:samples.map(({landmarks,...s})=>s)};}
let reportURL=null;
function reportText(){const r=report(),sm=r.summary,review=coach?.getReview(),sportName=sport==='basketball'?'籃球投籃':'高爾夫揮桿',lines=[];const clean=v=>String(v??'').replace(/[\r\n]+/g,' ').trim();const phaseLabels=sport==='basketball'?{dip:'準備最低點',rise:'開始上升',release:'出手',finish:'落地穩定'}:{address:'準備／地址位',top:'上桿頂點',impact:'擊球',finish:'收桿穩定'},aiPhases=sport==='basketball'?['準備','上升','出手']:['準備','上桿頂點附近','擊球附近'];const range=(x,d=1)=>x?`${number(x.min,d)}°–${number(x.max,d)}°（${x.count}/${sm.total} 個有效取樣）`:'可用取樣不足，無法計算';
lines.push(`# Motion Lab｜${sportName}重點分析報告`,'',`- 影片：${clean(r.filename||'未命名')}`,`- 日期：${new Date().toLocaleDateString('zh-TW')}`,`- 片長：${number(r.duration,2)} 秒 · 拍攝：${({side:'側面',front:'正面',rear:'後方'})[r.view]||r.view} · 慣用手：${r.hand==='right'?'右手':'左手'}`,'',`## 本次重點`,'',`- 人體姿勢偵測：${sm.detected}/${sm.total} 個取樣（${sm.total?Math.round(sm.detected/sm.total*100):0}%）。這代表關節偵測覆蓋率，不是動作分數。`,`- 手肘角度：${range(sm.elbow)}。`,`- 膝蓋角度：${range(sm.knee)}。`,`- 軀幹畫面投影角度：${range(sm.lean)}。`,`- 髖部水平活動範圍：${sm.horizontalSpan===null?'可用資料不足':`${number(sm.horizontalSpan*100)}% 軀幹長度（整段影片最大與最小值之差）`}。此值不是公分或前移距離。`,'');
if(r.marks&&Object.keys(r.marks).length){lines.push('## 動作階段時間（人工標記）','','| 階段 | 時間 |','|---|---:|');for(const [k,t] of Object.entries(r.marks))lines.push(`| ${phaseLabels[k]||k} | ${Number.isFinite(t)?`${t.toFixed(2)} 秒`:'—'} |`);if(r.timing?.complete)lines.push('',sport==='basketball'?`- 最低點→開始上升：${number(r.timing.durations[0],2)} 秒；開始上升→出手：${number(r.timing.durations[1],2)} 秒；出手→落地穩定：${number(r.timing.durations[2],2)} 秒。`:`- 上桿：${number(r.timing.durations[0],2)} 秒；下桿：${number(r.timing.durations[1],2)} 秒；節奏比：${number(r.timing.ratio,2)} : 1。`,'- 時刻由使用者逐格確認；角度／時間解析度受影片影格率與標記誤差影響，僅作本次回看定位，不當成理想值。');lines.push('');}
lines.push('## 可見細節與限制','');for(const item of r.observations)lines.push(`- ${clean(item)}`);if((sm.elbow?.count??0)<Math.max(5,sm.total*.2))lines.push('- 手肘角度有效點偏少，不宜用角度範圍推斷整段出手姿勢。');if((sm.knee?.count??0)<Math.max(5,sm.total*.2))lines.push('- 膝蓋角度有效點偏少，不宜判斷整段屈伸趨勢。');lines.push('- 量測為單鏡頭 2D 姿勢估計；軀幹傾斜與髖部畫面位移分開解讀。','- 本工具未追蹤籃球／球桿；無法單憑身體骨架確認人球同步、球離手／桿面接觸、力量或運動結果。','- 本報告只分析目前載入的影片；未提供另一支影片的量測時，不比較兩支影片的優劣或排名。','');
if(review){lines.push('## 動作調整建議（請對照原片核對）','',clean(review.summary));for(const o of review.observations??[])lines.push(`- ${aiPhases[o.phase]||'階段'} ${Number.isFinite(o.time)?`約 ${o.time.toFixed(2)} 秒 · `:''}${o.confidence==='low'?'需確認 · ':'觀察 · '}${clean(o.observation)} 細節：${clean(o.evidence)}`);for(const u of review.uncertainties??[])lines.push(`- 需確認：${clean(u)}`);if(review.corrections?.length){lines.push('','### 有影片細節支持的練習建議（非量測目標）');for(const c of review.corrections)lines.push(`- ${aiPhases[c.phase]||'階段'}${Number.isFinite(c.time)?`（約 ${c.time.toFixed(2)} 秒）`:''}：${clean(c.title)}。${clean(c.instruction)} 細節：${clean(c.evidence)}`);}else lines.push('');
if(review){const p=review.practice??{};lines.push('','### 下一次練習方向','',`- ${clean(p.title||'節奏與平衡練習')}：${clean(p.instruction||'以半速重複 5 次，保持動作連續與平衡；熟悉後再逐步恢復原速。')}`,`- ${clean(p.detail||'先建立穩定、可重複的動作節奏。')}`);}}
else lines.push('## 動作調整建議（尚未執行）','','尚未完成 AI 檢視；以下建議僅為回看方式，不代表這段影片有姿勢問題。');
lines.push('','## 下一次練習可觀察的重點','',sport==='basketball'?'- 以同一側面與固定鏡頭，重看「準備 → 開始上升 → 出手 → 落地」；先確認每個時刻，再比較不同投籃。\n- 分別觀察軀幹角度與髖部畫面位置；不要把畫面位移直接當成向籃框前移。\n- 若要檢查「球與身體一起下／一起上」，請在原片追蹤球相對身體的連續時序；目前工具沒有自動球體追蹤，因此報告不替這項同步性下結論。':'- 以相同角度重看準備、上桿頂點、擊球與收桿，並由使用者確認擊球時刻。\n- 本工具未追蹤球桿；桿面、桿路和擊球品質需用原片或專用設備另行確認。','',`> 本報告以量測覆蓋率、可見影格與使用者標記為依據；不提供技術評分、醫療診斷或效果保證。AI 觀察與建議需由使用者回看原片核對。`);return lines.join('\n');}
